118	                + GRADE_ON + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE))"
119	                + " ORDER BY r.from_date DESC NULLS LAST LIMIT 1", BigDecimal.class, sheetId,
120	                sheetId, claim.personId(), claim.date(), claim.date());
121	        if (pct.isEmpty()) return null;
122	        BigDecimal due = new BigDecimal(claim.amount()).multiply(pct.get(0)).movePointLeft(2)
123	                .setScale(2, rounding(sheetId, claim));
124	        return new BigDecimal(claim.amount()).signum() < 0 ? due : due.max(floor(sheetId));
125	    }
