130	    public RoundingMode rounding(String sheetId, Claim claim) {
131	        String date = claim.date();
132	        if (claim.corrects() != null) {
133	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
134	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
135	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
136	        }
137	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
138	                Date.class, sheetId);
139	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
140	        return LocalDate.parse(date).isBefore(policy.get(0).toLocalDate()) ? RoundingMode.HALF_UP
141	                : RoundingMode.HALF_EVEN;
142	    }
143	
144	    /** The sheet's floor: the least a live due can be (two decimals). */
145	    public BigDecimal floor(String sheetId) {
146	        List<BigDecimal> found = jdbc.queryForList("SELECT floor FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
147	        return found.isEmpty() || found.get(0) == null ? BigDecimal.ONE.setScale(2) : found.get(0).setScale(2);
148	    }
