151	     *  it to (not while PENDING), else its live due; null when it has none. */
152	    public BigDecimal figure(String sheetId, Claim claim) {
153	        if (claim.due() != null) return new BigDecimal(claim.due());
154	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
155	        return due(sheetId, claim);
156	    }
157	
158	    /** A claim's due now: its figure, plus, while it is overdue (OPEN or PENDING and its due-by — its date plus the
159	     *  sheet's terms — before the sheet's today), the sheet's late percent of that figure for every full
160	     *  30 days it is overdue, rounded to two decimals by the claim's rounding. A statement never binds the charge:
161	     *  it keeps following the sheet's today until settling freezes it in. A correction (a negative amount)
162	     *  has no late charge. Null when it has no figure. */
163	    public BigDecimal dueNow(String sheetId, Claim claim) {
164	        BigDecimal figure = figure(sheetId, claim);
165	        if (figure == null || !claim.open() || new BigDecimal(claim.amount()).signum() < 0) {
166	            return figure;
167	        }
168	        List<Object[]> found = jdbc.query("SELECT today, terms, late_pct FROM sheet WHERE id = ?",
169	                (rs, i) -> new Object[] { rs.getDate("today").toLocalDate(), rs.getInt("terms"),
170	                        rs.getBigDecimal("late_pct") }, sheetId);
171	        if (found.isEmpty()) return figure;
172	        LocalDate today = (LocalDate) found.get(0)[0];
173	        LocalDate dueBy = LocalDate.parse(claim.date()).plusDays((Integer) found.get(0)[1]);
174	        BigDecimal pct = (BigDecimal) found.get(0)[2];
175	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
176	        if (periods == 0 || pct == null || pct.signum() == 0) return figure;
177	        BigDecimal charge = figure.multiply(pct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
178	                .setScale(2, rounding(sheetId, claim));
179	        return figure.add(charge);
180	    }
