201	
202	    /** Move a DRAFT, OPEN or PENDING claim to another person: it is unbound from its last statement (live
203	     *  again) and listed as its new person's newest claim; false when the sheet has no such claim in those statuses. */
204	    public boolean reassign(String sheetId, long claimId, long personId) {
205	        return jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL,"
206	                + " listed = NEXT VALUE FOR claim_listed_seq WHERE id = ? AND sheet_id = ?"
207	                + " AND status IN ('DRAFT', 'OPEN', 'PENDING')", personId, claimId, sheetId) > 0;
208	    }
209	
210	    /** Fix a settled claim's due. */
211	    public void settleDue(String sheetId, long claimId, BigDecimal due) {
212	        jdbc.update("UPDATE claim SET settled_due = ? WHERE id = ? AND sheet_id = ?", due, claimId, sheetId);
213	    }
214	
215	    /** The name of a person on the sheet. */
216	    public String personName(String sheetId, long personId) {
217	        return jdbc.queryForObject("SELECT name FROM person WHERE sheet_id = ? AND id = ?",
218	                String.class, sheetId, personId);
219	    }
220	
221	    /** Whether the person has a SETTLED claim with this number on the sheet. */
222	    public boolean settledOf(String sheetId, long personId, String number) {
223	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
224	                + " AND claim_no = ? AND status = 'SETTLED'", Integer.class, sheetId, personId, number);
225	        return n != null && n > 0;
226	    }
227	
228	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
229	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
230	        jdbc.update(c -> {
231	            PreparedStatement ps = c.prepareStatement(
232	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects) VALUES (?, ?, ?, ?, ?, ?)",
233	                    new String[] { "id" });
234	            ps.setString(1, sheetId);
235	            ps.setLong(2, personId);
236	            ps.setBigDecimal(3, amount);
237	            ps.setDate(4, Date.valueOf(date));
238	            ps.setString(5, note);
239	            ps.setString(6, corrects);
240	            return ps;
241	        }, keys);
242	        return new Claim(keys.getKey().longValue(), personId, money(amount), date.toString(), note, "DRAFT", null, null, null, false, null, corrects);
243	    }
244	
245	    /** Change a DRAFT claim's amount, date, note and the number it corrects; false when the sheet has no
246	     *  such draft claim. */
247	    public boolean update(String sheetId, long claimId, BigDecimal amount, LocalDate date, String note, String corrects) {
248	        return jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ? WHERE id = ?"
249	                + " AND sheet_id = ? AND status = 'DRAFT'",
250	                amount, Date.valueOf(date), note, corrects, claimId, sheetId) > 0;
251	    }
252	
253	    /** An amount as shown: two decimals, a dot, no grouping. */
254	    static String money(BigDecimal amount) {
255	        return amount.setScale(2).toPlainString();
256	    }
257	
258	    /** A fixed due as shown, or null when there is none. */
259	    static String dueOf(BigDecimal due) {
260	        return due == null ? null : money(due);
261	    }
262	}
