package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingsRepository {
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";

    private final JdbcTemplate jdbc;

    public SettingsRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public boolean sheetExists(String sheetId) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
        return known != null && known > 0;
    }

    /** The sheet's settings and roles, roles by user name. */
    public Settings load(String sheetId) {
        List<Role> roles = jdbc.query("SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new Role(rs.getString("user_name"), rs.getString("role")), sheetId);
        BigDecimal limit = clerkLimit(sheetId);
        LocalDate policy = policyDate(sheetId);
        LocalDate numbering = periodNumberingFrom(sheetId);
        return new Settings(limit == null ? null : money(limit), money(floor(sheetId)), terms(sheetId),
                money(latePct(sheetId)), roles, policy == null ? null : policy.toString(),
                numbering == null ? null : numbering.toString());
    }

    /** The sheet's clerk limit; null when it has none. */
    public BigDecimal clerkLimit(String sheetId) {
        List<BigDecimal> found = jdbc.query("SELECT clerk_limit FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBigDecimal("clerk_limit"), sheetId);
        return found.isEmpty() ? null : found.get(0);
    }

    public void setClerkLimit(String sheetId, BigDecimal limit) {
        jdbc.update("UPDATE sheet SET clerk_limit = ? WHERE id = ?", limit, sheetId);
    }

    /** The sheet's floor: the least a live due can be; 1.00 unless set otherwise. */
    public BigDecimal floor(String sheetId) {
        List<BigDecimal> found = jdbc.query("SELECT floor FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBigDecimal("floor"), sheetId);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ONE : found.get(0);
    }

    public void setFloor(String sheetId, BigDecimal floor) {
        jdbc.update("UPDATE sheet SET floor = ? WHERE id = ?", floor, sheetId);
    }

    /** The sheet's terms: the days after a claim's date that it is due by; 14 unless set otherwise. */
    public int terms(String sheetId) {
        List<Integer> found = jdbc.query("SELECT terms FROM sheet WHERE id = ?",
                (rs, i) -> rs.getInt("terms"), sheetId);
        return found.isEmpty() ? 14 : found.get(0);
    }

    public void setTerms(String sheetId, int terms) {
        jdbc.update("UPDATE sheet SET terms = ? WHERE id = ?", terms, sheetId);
    }

    /** The sheet's late percent: what an overdue claim's due gains, of its figure, for every full 30 days
     *  it is overdue; 0.00 unless set otherwise. */
    public BigDecimal latePct(String sheetId) {
        List<BigDecimal> found = jdbc.query("SELECT late_pct FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBigDecimal("late_pct"), sheetId);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ZERO : found.get(0);
    }

    public void setLatePct(String sheetId, BigDecimal pct) {
        jdbc.update("UPDATE sheet SET late_pct = ? WHERE id = ?", pct, sheetId);
    }

    /** The sheet's policy date; null when blank (the sheet's today is then the policy date). */
    public LocalDate policyDate(String sheetId) {
        List<Date> found = jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                (rs, i) -> rs.getDate("policy_date"), sheetId);
        return found.isEmpty() || found.get(0) == null ? null : found.get(0).toLocalDate();
    }

    public void setPolicyDate(String sheetId, LocalDate policyDate) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", policyDate == null ? null : Date.valueOf(policyDate),
                sheetId);
    }

    /** The sheet's period numbering from-date; null when blank (period numbering is off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        List<Date> found = jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                (rs, i) -> rs.getDate("period_numbering_from"), sheetId);
        return found.isEmpty() || found.get(0) == null ? null : found.get(0).toLocalDate();
    }

    public void setPeriodNumberingFrom(String sheetId, LocalDate from) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", from == null ? null : Date.valueOf(from),
                sheetId);
    }

    /** The role a user name holds on the sheet: clerk unless set otherwise. */
    public String role(String sheetId, String user) {
        List<String> found = jdbc.query("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                (rs, i) -> rs.getString("role"), sheetId, user);
        return found.isEmpty() ? CLERK : found.get(0);
    }

    public void setRole(String sheetId, String user, String role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role);
    }

    /** A limit as shown: two decimals, a dot, no grouping. */
    public static String money(BigDecimal v) {
        return v.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the settings form: the clerk limit is 0.00 or more with up to two decimals, blank meaning no
 *  limit; the floor is 0.00 or more with up to two decimals; the terms are a whole number of days, 0 to
 *  3650; the late percent is 0.00 or more with up to two decimals; the policy date is a date
 *  (yyyy-mm-dd), blank meaning the sheet's today; the period
 *  numbering from-date is a date, blank meaning off. A setting left out is not changed. */
public class ValidateSettings {
    private static final Pattern MONEY = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?|\\.\\d{1,2}");
    private static final Pattern TERMS = Pattern.compile("\\d{1,4}");

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> settings)
            throws BadRequestException {
        String limit = request == null || request.clerkLimit() == null ? null : request.clerkLimit().trim();
        String floor = request == null || request.floor() == null ? null : request.floor().trim();
        String terms = request == null || request.terms() == null ? null : request.terms().trim();
        if (limit != null && !limit.isEmpty() && !MONEY.matcher(limit).matches()) {
            throw new BadRequestException("clerk limit must be 0.00 or more with up to two decimals");
        }
        if (floor != null && !MONEY.matcher(floor).matches()) {
            throw new BadRequestException("floor must be 0.00 or more with up to two decimals");
        }
        String latePct = request == null || request.latePct() == null ? null : request.latePct().trim();
        if (terms != null && (!TERMS.matcher(terms).matches() || Integer.parseInt(terms) > 3650)) {
            throw new BadRequestException("terms must be a whole number of days from 0 to 3650");
        }
        if (latePct != null && !MONEY.matcher(latePct).matches()) {
            throw new BadRequestException("late percent must be 0.00 or more with up to two decimals");
        }
        String policy = request == null || request.policyDate() == null ? null : request.policyDate().trim();
        LocalDate policyDate = null;
        if (policy != null && !policy.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policy);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("policy date must be a date (yyyy-mm-dd)");
            }
        }
        String numbering = request == null || request.periodNumberingFrom() == null ? null
                : request.periodNumberingFrom().trim();
        LocalDate numberingFrom = null;
        if (numbering != null && !numbering.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numbering);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("period numbering from must be a date (yyyy-mm-dd)");
            }
        }
        settings.set(new SettingsInput(limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor != null, floor == null ? null : new BigDecimal(floor).setScale(2),
                terms != null, terms == null ? null : Integer.parseInt(terms),
                latePct != null, latePct == null ? null : new BigDecimal(latePct).setScale(2),
                policy != null, policyDate, numbering != null, numberingFrom));
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input,
            ServerHttpConnection connection, SettingsRepository repository, Audit audit, Rollup rollup,
            Out<Settings> settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        Rollup.Snapshot before = rollup.take(id);
        if (input.setsClerkLimit()) {
            repository.setClerkLimit(id, input.clerkLimit());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=clerk-limit value="
                    + (input.clerkLimit() == null ? "" : SettingsRepository.money(input.clerkLimit())));
        }
        if (input.setsFloor()) {
            repository.setFloor(id, input.floor());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=floor value="
                    + SettingsRepository.money(input.floor()));
        }
        if (input.setsTerms()) {
            repository.setTerms(id, input.terms());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=terms value=" + input.terms());
        }
        if (input.setsLatePct()) {
            repository.setLatePct(id, input.latePct());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=late-pct value="
                    + SettingsRepository.money(input.latePct()));
        }
        if (input.setsPolicyDate()) {
            repository.setPolicyDate(id, input.policyDate());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=policy-date value="
                    + (input.policyDate() == null ? "" : input.policyDate().toString()));
        }
        if (input.setsPeriodNumberingFrom()) {
            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=period-numbering-from value="
                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom().toString()));
        }
        rollup.record(id, by, before);
        settings.set(repository.load(id));
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated settings form: which settings it saves, the clerk limit scaled to two decimals (null for
 *  no limit), the floor scaled to two decimals the terms in days and the late percent scaled to two decimals and the policy date (null when blank), and the period numbering from-date (null when blank: off). */
public record SettingsInput(boolean setsClerkLimit, BigDecimal clerkLimit, boolean setsFloor, BigDecimal floor, boolean setsTerms,
        Integer terms, boolean setsLatePct, BigDecimal latePct,
        boolean setsPolicyDate, LocalDate policyDate, boolean setsPeriodNumberingFrom, LocalDate periodNumberingFrom) {
}
package net.officefloor.hq.app.settings;

import java.util.List;

/** A sheet's settings: its clerk limit (two decimals; null means no limit), its floor (two decimals:
 *  the least a live due can be), its terms (the days after a claim's date that it is due by), its late percent (two decimals: what an
 *  overdue claim's due gains, of its figure, for every full 30 days it is overdue), the roles set on it, by user name. A name not listed is a clerk. And its policy date (yyyy-MM-dd; null when blank,
 *  meaning the sheet's today): a claim dated before it rounds half up, one on or after it half to even. And its period numbering from-date (yyyy-MM-dd; null when blank, meaning off):
 *  while set and the sheet's today is on or after it, a claim opened is numbered within its period. */
public record Settings(String clerkLimit, String floor, int terms, String latePct, List<Role> roles, String policyDate,
        String periodNumberingFrom) {
}
package net.officefloor.hq.app.claim;

/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED or VOID), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
